package com.bank.cleaner;

import java.util.logging.Logger;

// Cleans account identifiers for National Bank of India before storage/lookup.
public class IdentifierCleaner {
    private static final Logger log = Logger.getLogger(IdentifierCleaner.class.getName());

    // Removes only the ASCII space character.
    public String removeSpaces(String s) {
        if (s == null) return null;
        StringBuilder sb = new StringBuilder(s.length()); // pre-size for speed
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != ' ') {            // keep everything except a plain space
                sb.append(c);
            }
        }
        String cleaned = sb.toString();
        log.fine(() -> "removeSpaces '" + s + "' -> '" + cleaned + "'");
        return cleaned;
    }

    // Removes every whitespace: space, tab, newline, carriage return, etc.
    public String removeAllWhitespace(String s) {
        if (s == null) return null;
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!Character.isWhitespace(c)) {   // whitespace-aware
                sb.append(c);
            }
        }
        String cleaned = sb.toString();
        log.fine(() -> "removeAllWhitespace -> '" + cleaned + "'");
        return cleaned;
    }
}
