package com.bank.cleaner;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: clean pasted account identifiers.
public class CleanerDemo {
    private static final Logger log = Logger.getLogger(CleanerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        IdentifierCleaner cleaner = new IdentifierCleaner();

        String rajeshAccount = "SAV 2001";            // spaces only
        String pastedCode    = "CUR\t3001\n";          // tab + newline

        String a = cleaner.removeSpaces(rajeshAccount);
        log.info(() -> "Rajesh account cleaned (spaces only): '" + a + "'");

        String b = cleaner.removeAllWhitespace(pastedCode);
        log.info(() -> "Priya pasted code cleaned (all whitespace): '" + b + "'");
    }
}
